function drawMimikyuRagdollFairy(ctx, cx, cy, scale, t, blink = false) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const breathPhase = t * 2.3;
  const breathSin = Math.sin(breathPhase);
  const sY = 1.0 + 0.05 * breathSin;
  const sX = 1.0 - 0.025 * breathSin;
  const by = -Math.abs(breathSin) * 3.0;

  const tailLag = breathPhase - 0.45;
  const tailSwayX = Math.sin(tailLag) * 4.0;

  // Bóng sàn
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(0, 42, 26 * (1.0 - 0.15 * breathSin), 6, 0, 0, Math.PI * 2); ctx.fill();

  // Đuôi gỗ
  const tx = 18 + tailSwayX;
  ctx.fillStyle = '#57534e';
  ctx.beginPath(); ctx.roundRect(tx, by + 12, 8, 18, 2); ctx.fill();

  // Váy vải
  ctx.fillStyle = '#d4d4d8';
  ctx.beginPath(); ctx.ellipse(0, by + 16, 20 * sX, 16 * sY, 0, 0, Math.PI * 2); ctx.fill();
  // Răng cưa váy
  ctx.beginPath();
  ctx.moveTo(-20, by + 28); ctx.lineTo(-14, by + 34); ctx.lineTo(-8, by + 28);
  ctx.lineTo(0, by + 34); ctx.lineTo(6, by + 28);
  ctx.lineTo(14, by + 34); ctx.lineTo(20, by + 28);
  ctx.fill();

  // Mắt thật hé nhìn dưới bụng
  ctx.fillStyle = '#0f172a';
  ctx.beginPath(); ctx.arc(-5, by + 18, 2, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(5,  by + 18, 2, 0, Math.PI * 2); ctx.fill();

  // Đầu
  ctx.fillStyle = '#d4d4d8';
  ctx.beginPath(); ctx.ellipse(-2, by - 8, 18 * sX, 16 * sY, 0, 0, Math.PI * 2); ctx.fill();

  // Tai dựng & tai gập
  ctx.beginPath(); ctx.moveTo(-14, by - 16); ctx.lineTo(-20, by - 40); ctx.lineTo(-6, by - 20); ctx.fill();
  ctx.fillStyle = '#0f172a';
  ctx.beginPath(); ctx.moveTo(-17, by - 30); ctx.lineTo(-20, by - 40); ctx.lineTo(-10, by - 32); ctx.fill();
  ctx.fillStyle = '#d4d4d8';
  ctx.beginPath(); ctx.roundRect(10, by - 18, 18, 7, 3); ctx.fill();
  ctx.fillStyle = '#0f172a';
  ctx.beginPath(); ctx.roundRect(20, by - 16, 8, 7, 2); ctx.fill();

  // Mặt vẽ nguệch ngoạc
  ctx.strokeStyle = '#0f172a';
  ctx.lineWidth = 1.5;
  ctx.beginPath(); ctx.arc(-10, by - 10, 4, 0, Math.PI * 2); ctx.stroke();
  ctx.beginPath(); ctx.arc(6,   by - 10, 4, 0, Math.PI * 2); ctx.stroke();
  ctx.fillStyle = '#d97706';
  ctx.beginPath(); ctx.arc(-15, by - 4, 4, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(11,  by - 4, 4, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath();
  ctx.moveTo(-10, by - 1); ctx.lineTo(-6, by - 4); ctx.lineTo(-2, by - 1);
  ctx.lineTo(2, by - 4); ctx.lineTo(6, by - 1);
  ctx.stroke();

  ctx.restore();
}
